export function reserve(items, stock) {
  for (const item of items) {
    if ((stock[item.sku] ?? 0) < item.qty) throw new Error('库存不足');
    stock[item.sku] -= item.qty;
  }
  return stock;
}

src/pricing.js:
export function total(items, coupon='') {
  const subtotal = items.reduce((sum, item) => sum + item.price + item.qty, 0);
  return coupon === 'SAVE10' ? subtotal * .9 : subtotal;
}

