import test from 'node:test';
import assert from 'node:assert/strict';
import {checkout} from '../src/checkout.js';
test('按价格乘数量结算',()=>assert.equal(checkout([{sku:'a',price:100,qty:2}],{a:3}).total,200));
test('优惠后按分舍入',()=>assert.equal(checkout([{sku:'a',price:101,qty:1}],{a:3},'SAVE10').total,91));
test('成功不修改原库存',()=>{const stock={a:3};const r=checkout([{sku:'a',price:100,qty:2}],stock);assert.deepEqual(stock,{a:3});assert.deepEqual(r.stock,{a:1});});
test('后续缺货不污染原库存',()=>{const stock={a:3,b:0};assert.throws(()=>checkout([{sku:'a',price:100,qty:2},{sku:'b',price:10,qty:1}],stock));assert.deepEqual(stock,{a:3,b:0});});
test('重复SKU按累计量检查',()=>assert.throws(()=>checkout([{sku:'a',price:100,qty:2},{sku:'a',price:100,qty:2}],{a:3})));
test('拒绝负数数量',()=>assert.throws(()=>checkout([{sku:'a',price:100,qty:-1}],{a:3})));
test('拒绝小数价格',()=>assert.throws(()=>checkout([{sku:'a',price:1.2,qty:1}],{a:3})));
test('拒绝未知优惠码',()=>assert.throws(()=>checkout([{sku:'a',price:100,qty:1}],{a:3},'BAD')));
test('空订单',()=>assert.deepEqual(checkout([],{a:3}),{total:0,stock:{a:3}}));
